/* -------------------------------------------------------------------------------------------------
 * MessageFeedback
 * -----------------------------------------------------------------------------------------------*/

/**
 * Thumbs up and down. Up says thanks. Down asks what went wrong, inline or in a popover, and
 * then says thanks. Place it inside `MessageActions`; its parts join the toolbar row.
 */
export function MessageFeedback({
  value: valueProp,
  defaultValue = null,
  onValueChange,
  reasons = DEFAULT_REASONS,
  reasonMode = "chips",
  onReason,
  thanks = "Thanks for the feedback",
  className,
  ...props
}: MessageFeedbackProps) {
  const [valueState, setValueState] = React.useState<FeedbackValue | null>(defaultValue)
  const value = valueProp !== undefined ? valueProp : valueState
  const [asking, setAsking] = React.useState(false)
  const [picked, setPicked] = React.useState<string[]>([])
  const [note, setNote] = React.useState("")
  const [thanksPhase, setThanksPhase] = React.useState<"hidden" | "in" | "out">("hidden")
  // Animate the icon swap only for pointer clicks. Keyboard-triggered changes are instant.
  const [animate, setAnimate] = React.useState(false)
  const pointer = React.useRef(false)
  const titleId = React.useId()

  React.useEffect(() => {
    if (thanksPhase === "hidden") return
    const id = window.setTimeout(
      () => setThanksPhase(thanksPhase === "in" ? "out" : "hidden"),
      thanksPhase === "in" ? 2400 : 150,
    )
    return () => window.clearTimeout(id)
  }, [thanksPhase])

  const set = (next: FeedbackValue | null) => {
    setAnimate(pointer.current)
    pointer.current = false
    if (valueProp === undefined) setValueState(next)
    onValueChange?.(next)
  }

  const choose = (kind: FeedbackValue) => {
    const next = value === kind ? null : kind
    set(next)
    setPicked([])
    setNote("")
    if (next === "down" && reasons.length > 0) {
      setAsking(true)
      setThanksPhase("hidden")
    } else {
      setAsking(false)
      setThanksPhase(next ? "in" : "hidden")
    }
  }

  const submit = (list: string[], text?: string) => {
    onReason?.(list, text?.trim() || undefined)
    setAsking(false)
    setThanksPhase("in")
  }

  const markPointer = () => {
    pointer.current = true
  }

  const group = (
    // biome-ignore lint/a11y/useSemanticElements: a pair of toggles, not a form fieldset
    <div
      role="group"
      aria-label="Rate this response"
      data-slot="message-feedback"
      data-feedback={value ?? undefined}
      // `contents` lets the thumbs and the reason row join the toolbar's flex row.
      className={cn("contents", className)}
      {...props}
    >
      <Thumb
        kind="up"
        active={value === "up"}
        animate={animate}
        onPointerDown={markPointer}
        onClick={() => choose("up")}
      />
      {reasonMode === "popover" ? (
        <Popover.Trigger
          render={
            <Thumb
              kind="down"
              active={value === "down"}
              animate={animate}
              onPointerDown={markPointer}
              onClick={() => choose("down")}
            />
          }
        />
      ) : (
        <Thumb
          kind="down"
          active={value === "down"}
          animate={animate}
          onPointerDown={markPointer}
          onClick={() => choose("down")}
        />
      )}

      {/* After every other action in the row, so saying thanks never pushes a button aside. */}
      <span
        aria-live="polite"
        data-slot="message-feedback-thanks"
        className={cn(
          "text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) order-last ms-1.5",
          "ease-(--chatcn-ease-out) transition-opacity duration-150 starting:opacity-0",
          thanksPhase === "out" && "opacity-0 duration-110",
          thanksPhase === "hidden" && "sr-only",
        )}
      >
        {thanksPhase === "hidden" ? "" : thanks}
      </span>

      {asking && reasonMode === "chips" ? (
        <div
          data-slot="message-feedback-reasons"
          className={cn(
            "order-last ms-1.5 mt-1.5 flex basis-full flex-wrap items-center gap-1.5",
            "motion-safe:animate-[chatcn-enter_180ms_var(--chatcn-ease-out)]",
          )}
        >
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) me-0.5">What went wrong?</span>
          {reasons.map((reason) => (
            <ReasonChip key={reason} onClick={() => submit([reason])}>
              {reason}
            </ReasonChip>
          ))}
          <Button
            size="icon-xs"
            aria-label="Skip"
            onClick={() => setAsking(false)}
            className="text-(color:--chatcn-fg-subtle)"
          >
            <XIcon />
          </Button>
        </div>
      ) : null}

      {reasonMode === "popover" ? (
        <Popover.Portal>
          <Popover.Positioner
            side="bottom"
            align="start"
            sideOffset={6}
            className="z-50 outline-none"
          >
            <Popover.Popup
              aria-labelledby={`${titleId}`}
              data-slot="message-feedback-popover"
              className={cn(
                "rounded-(--chatcn-radius-xl) bg-(color:--chatcn-surface) shadow-(--chatcn-shadow-lg) w-80 max-w-[calc(100vw-2rem)] origin-(--transform-origin) p-3 outline-none",
                "ease-(--chatcn-ease-out) transition-[opacity,scale] duration-180",
                "data-[starting-style]:scale-96 data-[starting-style]:opacity-0",
                "data-[ending-style]:scale-98 data-[ending-style]:opacity-0 data-[ending-style]:duration-140",
                "data-[instant]:transition-none motion-reduce:transition-none",
              )}
            >
              <form
                className="flex flex-col gap-3"
                onSubmit={(event) => {
                  event.preventDefault()
                  submit(picked, note)
                }}
              >
                <h2 id={titleId} className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) font-medium">
                  What went wrong?
                </h2>
                <div className="flex flex-wrap gap-1.5">
                  {reasons.map((reason) => (
                    <ReasonChip
                      key={reason}
                      pressed={picked.includes(reason)}
                      onClick={() =>
                        setPicked((list) =>
                          list.includes(reason)
                            ? list.filter((r) => r !== reason)
                            : [...list, reason],
                        )
                      }
                    >
                      {reason}
                    </ReasonChip>
                  ))}
                </div>
                <textarea
                  value={note}
                  onChange={(event) => setNote(event.target.value)}
                  onKeyDown={(event) => {
                    if (event.key !== "Enter" || event.shiftKey) return
                    if (event.nativeEvent.isComposing || event.keyCode === 229) return
                    event.preventDefault()
                    event.currentTarget.form?.requestSubmit()
                  }}
                  rows={2}
                  aria-label="Details"
                  placeholder="What should the answer have said…"
                  className={cn(
