  useLoop(async (wait) => {
    setSent(null)
    setRound((r) => r + 1)
    await wait(1100)
    await tap(g, 'button[aria-label="Bad response"]', wait)
    await wait(900)
    await tap(g, '[data-slot="message-feedback-reasons"] button:nth-of-type(2)', wait, 800)
    await wait(300)
    g.hide()
    await wait(3000)
    setSent(null)
    setRound((r) => r + 1)
    await wait(900)
    await tap(g, 'button[aria-label="Good response"]', wait)
    await wait(300)
    g.hide()
    await wait(2800)
  }, touring)

  return (
    <FitFrame minWidth="38rem">
      <div className="flex w-full flex-col items-center justify-center gap-4 p-6">
        <TooltipProvider>
          <div
            ref={stage}
            className="relative flex w-full max-w-2xl flex-col gap-5 overflow-hidden"
            onPointerDown={() => {
              if (!touring) return
              setTouring(false)
              g.hide()
            }}
          >
            <Message from="user">
              <MessageContent>{ask}</MessageContent>
            </Message>
            <div className="min-h-[9.5rem]">
              <Message from="assistant" latest>
                <MessageContent>{reply}</MessageContent>
                <MessageActions>
                  <MessageActionCopy value={reply} label="Copy response" />
                  <MessageFeedback
                    key={round}
                    reasons={REASONS}
                    onValueChange={(rating) => setSent(rating ? { rating } : null)}
                    onReason={(reasons) =>
                      setSent((s) => (s ? { ...s, reason: reasons.join(", ") } : s))
                    }
                  />
                </MessageActions>
              </Message>
            </div>
            <div className="rounded-(--chatcn-radius-lg) bg-(color:--chatcn-inset) text-[0.75rem]/[1rem] flex h-9 items-center gap-2 px-3 font-mono">
              <span className="text-(color:--chatcn-fg-subtle)">Sent</span>
              {sent ? (
                <span className="text-(color:--chatcn-fg)">
                  {`{ rating: "${sent.rating}"${sent.reason ? `, reason: "${sent.reason}"` : ""} }`}
                </span>
              ) : (
                <span className="text-(color:--chatcn-fg-faint)">waiting for a rating</span>
              )}
            </div>
            <Ghost ghost={g.ghost} />
          </div>
        </TooltipProvider>
        <MoreOn slug="message-feedback">Thumbs up and down, with reasons when a reply misses. On</MoreOn>
      </div>
    </FitFrame>
  )
}
